use hmac::{Hmac, Mac};
use sha2::Sha256;

pub fn verify_jwt_signature(token: &str, secret: &[u8]) -> bool {
    // Parse and verify the HMAC-SHA256 signature
    let parts: Vec<&str> = token.split('.').collect();
    if parts.len() != 3 { return false; }
    let mut mac = Hmac::<Sha256>::new_from_slice(secret).expect("valid key length");
    mac.update(format!("{}.{}", parts[0], parts[1]).as_bytes());
    let expected = base64url_decode(parts[2]);
    mac.verify_slice(&expected).is_ok()
}
